import{z as n,x as A,o as r,c as B,q as o,j as l,D as e,d as t,s,S as p,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"直接映射与高端内存","description":"","frontmatter":{"title":"直接映射与高端内存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/direct-map-highmem.md","filePath":"cs/direct-map-highmem.md","lastUpdated":1791413859000}'),d={name:"cs/direct-map-highmem.md"};function m(c,a,M,h,u,D){const i=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=o('<h1 id="直接映射与高端内存" tabindex="-1">直接映射与高端内存 <a class="header-anchor" href="#直接映射与高端内存" aria-label="Permalink to &quot;直接映射与高端内存&quot;">​</a></h1><div class="epigraph"><p>直接映射把物理内存线性映进内核虚址，pfn 与 va 可算术互转；32 位高内存超出该窗口，必须临时 kmap。</p><footer>—— 据 Gorman；Bovet and Cesati 对 ZONE_HIGHMEM 的整理；Linux 内存模型文档</footer></div><p><a href="/cs/vmalloc">vmalloc</a> 是稀疏内核映射。<a href="/cs/user-kernel-split">用户/内核分裂</a> 已有高半。缺口是 <strong>线性映射（direct map）</strong> 与历史 <strong>HIGHMEM</strong>：为何 64 位几乎不再提高端，以及安全上 direct map 别名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核常要「页框 → 可解引用指针」。direct map：<code>page_address</code> 即 va。32 位 4G 虚空间要分给用户，线性窗口盖不住全部 RAM → HIGHMEM，访问用 <code>kmap</code>。64 位 canonical 空间足够，HIGHMEM 消失。缺口：direct map 与用户映射同一页造成别名，<a href="/cs/kpti-os">KPTI</a> 与加固后课会动这份映射。本课不把每架构的起始地址当考纲。</p><p><span class="marginnote">huge 线性映射用大页覆盖 DRAM，省 TLB。加密内存、kfence 可能拆开部分线性映射。</span></p><p><span class="marginnote">术语翻译：pfn（page frame number，页框号）就是「物理地址 ÷ 页大小」得到的编号，相当于给每个 4 KB 页框发的身份证号。数字实例：页大小 \\(4096=2^{12}\\) 时，物理地址 \\(0{,}12345000_{16}\\) 的 pfn 就是 \\(0{,}12345_{16}\\)——直接右移 12 位，不用查任何表，这正是「直接映射」省事的根源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配页后内核用 <code>page_to_virt</code> 写。DMA coherent 也常靠这。HIGHMEM：kmap 在固定窗口建临时 pte。对照 vmalloc：direct map 覆盖全部（64 位）物理，vmalloc 是额外窗口。对照 DAX：用户直接映射 PMEM，内核仍有自己的 map。</p>',9)),(r(),l(p,null,{default:e(()=>[s(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PFN%5B%22%E7%89%A9%E7%90%86%E9%A1%B5%E5%8F%B7%22%5D%20--%3E%20DIR%5B%22%E7%9B%B4%E6%8E%A5%E6%98%A0%E5%B0%84%20va%22%5D%0A%20%20HIGH%5B%2232%20%E4%BD%8D%20HIGHMEM%22%5D%20--%3E%20KM%5B%22kmap%20%E4%B8%B4%E6%97%B6%E7%AA%97%22%5D%0A%20%20DIR%20--%3E%20PTR%5B%22%E5%86%85%E6%A0%B8%E6%8C%87%E9%92%88%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"线性映射让内核把 RAM 当大数组，是伙伴分配器实现的前提。HIGHMEM 是 32 位的补丁课，今日仍在旧嵌入式出现。不要写成 x86 分段课。与热插拔：新内存要纳入线性映射或稀疏 memmap。",-1)),a[5]||(a[5]=E("p",null,"别名：同一页框两个 va（用户+direct）在缓存别名架构上要命；x86 较宽松，仍有安全含义。",-1)),(r(),l(p,null,{default:e(()=>[s(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20T32%5B%2232%20%E4%BD%8D%EF%BC%9A%E5%85%B1%204%20GB%20%E8%99%9A%E5%9C%B0%E5%9D%80%22%5D%0A%20%20%20%20U%5B%22%E7%94%A8%E6%88%B7%E7%A9%BA%E9%97%B4%200%E2%80%933%20GB%22%5D%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E7%BA%BF%E6%80%A7%E7%AA%97%E5%8F%A3%203%E2%80%934%20GB%22%5D%0A%20%20%20%20K%20--%3E%20L1%5B%22%E4%BD%8E%E6%AE%B5%EF%BC%9A%E8%A6%86%E7%9B%96%E4%BD%8E%201%20GB%20RAM%EF%BC%8C%E5%8F%AF%E7%9B%B4%E6%98%A0%22%5D%0A%20%20%20%20K%20--%3E%20H%5B%22%E8%A3%85%E4%B8%8D%E4%B8%8B%E7%9A%84%20RAM%EF%BC%9AZONE_HIGHMEM%22%5D%0A%20%20%20%20H%20--%3E%20KM%5B%22kmap%EF%BC%9A%E5%80%9F%E4%B8%B4%E6%97%B6%E7%AA%97%E5%8F%A3%E9%80%90%E9%A1%B5%E6%98%A0%E5%B0%84%22%5D%0A%20%20end%0A%20%20subgraph%20T64%5B%2264%20%E4%BD%8D%EF%BC%9A%E8%99%9A%E5%9C%B0%E5%9D%80%E4%BB%A5%20TB%20%E8%AE%A1%22%5D%0A%20%20%20%20ALL%5B%22%E7%BA%BF%E6%80%A7%E7%AA%97%E5%8F%A3%E8%BF%9C%E5%A4%A7%E4%BA%8E%20RAM%EF%BC%9A%E5%85%A8%E9%83%A8%E7%9B%B4%E6%98%A0%EF%BC%8C%E6%97%A0%E9%9C%80%20HIGHMEM%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p>这张图回答「为什么 HIGHMEM 是 32 位专属补丁」：32 位总共只有 4 GB 虚地址，按 3G/1G 切给用户和内核后，内核线性窗口只有 1 GB；机器插 4 GB RAM 时多出的 3 GB 进不了直映，只能靠 <code>kmap</code> 借临时窗口逐页访问。64 位窗口以 TB 计，远超任何 RAM，问题整个消失。</p><p><span class="marginnote">常见误区：初学者容易把 <code>kmap</code> 想成「把数据拷进窗口」。它不搬一个字节，只是在内核页表里临时借一个虚地址指到目标页框，用完 <code>kunmap</code> 还回去；真正的数据访问仍走这个指针。窗口数量有限，长期占用会把别的 kmap 饿死。</span></p><p>实现上：线性映射用大页覆盖能显著减内核 TLB miss。KASLR 随机化内核映像但不随机整份直映。HIGHMEM 的 kmap 窗口有限，嵌套 kmap 要按类型取。 读法上只引用<a href="/cs/vmalloc">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「内存进阶 / 回收、迁移与加固」课序里，对象是 <strong>直接映射与高端内存</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MIPS 缓存别名的全部。不保证 confidential computing 下的共享 direct map。下一课为侧信道拆用户页表里的内核：KPTI。</p><p>版本字段会变，课序钉的是机制对象「直接映射与高端内存」，不是某一主线内核的结构体名。 后课默认：内核经线性映射碰页框。用户页表是否包含内核，下一课 KPTI。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>直接映射：pfn 与内核 va 线性对应。</li><li>HIGHMEM 是 32 位窗口不足的产物。</li><li>KPTI 是下一课。</li><li>出处：Gorman；<em>ULK</em>；Linux memory models。</li></ul>',10))])}const H=n(d,[["render",m]]);export{_ as __pageData,H as default};
